            eprint("    No such file or directory (os error 2)")
        else:
            eprint("Error: No such file or directory (os error 2)")
        return 1
    if mode == "file":
        return run_cmd([node, data])
    if mode == "stdin":
        return run_cmd([node], input_data=data)
    return run_cmd([node, "-e", data])

def run_ruby(mode, data):
