class CliError(SystemExit):
    pass

def eprint(s=""):
    print(s, file=sys.stderr)

def parse_exit(message, usage=None, tips=None):
    eprint(message)
    eprint()
    if tips:
        for t in tips:
            eprint(t)
        eprint()
    if usage:
        eprint(f"Usage: {usage}")
        eprint()
    eprint("For more information, try '--help'.")
    raise SystemExit(2)

def missing_value(opt):
    parse_exit(f"error: a value is required for '{opt}' but none was supplied")

def duplicate(opt, usage="executable [OPTIONS] [ARGS]..."):
    parse_exit(f"error: the argument '{opt}' cannot be used multiple times", usage=usage)

def unexpected_arg(arg, usage=None, similar=None):
    if usage is None:
        usage = "executable [OPTIONS] [ARGS]..."
    tips = []
    if similar:
        tips.append(f"  tip: a similar argument exists: '{similar}'")
    tips.append(f"  tip: to pass '{arg}' as a value, use '-- {arg}'")
    parse_exit(f"error: unexpected argument '{arg}' found", usage=usage, tips=tips)

def unexpected_value(value, opt, usage):
    parse_exit(f"error: unexpected value '{value}' for '{opt}' found; no more were expected", usage=usage)

def set_once(state, key, value, opt_display):
    if state.get(key) is not None if key in ("lang", "file", "code") else state.get(key):
        duplicate(opt_display)
    state[key] = value

def option_specific_usage(opt):
    if opt == "--lang": return "executable --lang <LANG> [ARGS]..."
    if opt == "--file": return "executable --file <PATH> [ARGS]..."
    if opt == "--code": return "executable --code <CODE> [ARGS]..."
    if opt == "--version": return "executable --version [ARGS]..."
    if opt == "--help": return "executable --help [ARGS]..."
    if opt == "--no-detect": return "executable --no-detect [ARGS]..."
    return "executable [OPTIONS] [ARGS]..."

def similar_long(tok):
    names = ["--lang", "--file", "--code", "--version", "--help", "--no-detect"]
    for n in names:
        if tok.startswith(n[:5]) or n.startswith(tok):
            return n
    # A couple of common clap suggestions observed for misspelled full names.
    base = tok.split("=", 1)[0]
    for n in names:
        if base[:4] == n[:4] or base[:-1] == n[:-1]:
            return n
    return None

def parse_argv(argv):
    state = {"lang": None, "file": None, "code": None, "no_detect": False, "version": False}
    args = []
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            args = argv[i+1:]
            break
        if tok == "-" or not tok.startswith("-"):
            args = argv[i:]
            break
        # long options
        if tok.startswith("--"):
            if tok == "--help":
                sys.stdout.write(HELP_TEXT)
                raise SystemExit(0)
            if tok.startswith("--help="):
                unexpected_value(tok.split("=",1)[1], "--help", "executable --help [ARGS]...")
            if tok == "--version":
                if state["version"]:
                    duplicate("--version")
                state["version"] = True
                i += 1
                continue
            if tok.startswith("--version="):
                unexpected_value(tok.split("=",1)[1], "--version", "executable --version [ARGS]...")
            if tok == "--no-detect":
                if state["no_detect"]:
                    duplicate("--no-detect")
                state["no_detect"] = True
                i += 1
                continue
            if tok.startswith("--no-detect="):
                unexpected_value(tok.split("=",1)[1], "--no-detect", "executable --no-detect [ARGS]...")

            handled = False
            for name, key, display in [("--lang", "lang", "--lang <LANG>"), ("--file", "file", "--file <PATH>"), ("--code", "code", "--code <CODE>")]:
                if tok == name or tok.startswith(name + "="):
                    if state[key] is not None:
                        duplicate(display)
                    if tok == name:
                        if i + 1 >= len(argv) or argv[i+1] == "" or argv[i+1].startswith("-"):
                            missing_value(display)
                        val = argv[i+1]
                        i += 2
                    else:
                        val = tok.split("=", 1)[1]
                        if val == "":
                            missing_value(display)
                        i += 1
                    state[key] = val
                    handled = True
                    break
            if handled:
                continue
            sim = similar_long(tok.split("=",1)[0])
            usage = option_specific_usage(sim) if sim else ("executable --version [ARGS]..." if state["version"] else "executable [OPTIONS] [ARGS]...")
            unexpected_arg(tok.split("=",1)[0], usage=usage, similar=sim)
        # short options / clusters
        j = 1
        while j < len(tok):
            ch = tok[j]
            if ch == "h":
                sys.stdout.write(HELP_TEXT)
                raise SystemExit(0)
            if ch == "V":
                if state["version"]:
                    duplicate("--version")
                state["version"] = True
                j += 1
                continue
            if ch in ("l", "f", "c"):
                key = {"l": "lang", "f": "file", "c": "code"}[ch]
                display = {"l": "--lang <LANG>", "f": "--file <PATH>", "c": "--code <CODE>"}[ch]
                if state[key] is not None:
                    duplicate(display)
                if j + 1 < len(tok):
                    val = tok[j+1:]
                    # Inline short values may be empty only if no remainder; here they are non-empty.
                    state[key] = val
                    j = len(tok)
                    break
                else:
                    if i + 1 >= len(argv) or argv[i+1] == "" or argv[i+1].startswith("-"):
                        missing_value(display)
                    state[key] = argv[i+1]
                    i += 1
                    j = len(tok)
                    break
            # Unknown short argument; clap reports just this character as -x / -=.
            unexpected_arg("-" + ch)
        i += 1
    if state["version"]:
        sys.stdout.write(VERSION_TEXT)
        raise SystemExit(0)
    return state, args

def norm_key(s):
    return s.strip().lower()

def normalize_lang(s):
    return ALIASES.get(norm_key(s))

def is_lang(s):
    return normalize_lang(s) is not None

def unknown_language(lang):
    eprint(f"Error: Unknown language '{norm_key(lang)}'. Available languages: {AVAILABLE_STR}")
    return 1

def ext_language(path):
    suffix = Path(path).suffix
    if suffix in EXT_LANG_CASE:
        return EXT_LANG_CASE[suffix]
    return EXT_LANG.get(suffix.lower())

def looks_like_file(tok):
    if tok == "":
        return True
    if os.path.exists(tok):
        return True
    if "/" in tok or tok.startswith("."):
        return True
    return ext_language(tok) is not None

def strip_leading_c_comments(s):
    t = s.lstrip()
    changed = True
    while changed:
        changed = False
        if t.startswith("/*"):
            end = t.find("*/")
            if end != -1:
                t = t[end+2:].lstrip()
                changed = True
        if t.startswith("//"):
            nl = t.find("\n")
            if nl != -1:
                t = t[nl+1:].lstrip()
                changed = True
    return t

def detect_language(code, no_detect=False):
    if no_detect:
        return "python"
    s = code or ""
    t = s.lstrip()
    low = t.lower()
    cskip = strip_leading_c_comments(s)
    cskip_low = cskip.lower()

    if low.startswith("#!") and ("sh" in low.split("\n",1)[0] or "bash" in low.split("\n",1)[0]):
        return "bash"
    if "<?php" in low:
        return "php"
    if "#include" in cskip_low:
        if "iostream" in cskip_low or "std::" in cskip:
            return "cpp"
        return "c"
    if low.startswith("package main"):
        return "go"
    if low.startswith("public class"):
        return "java"
    if low.startswith("fun main"):
        return "kotlin"
    if low.startswith("void main"):
        return "dart"
    if low.startswith("defmodule") or low.startswith("io.puts"):
        return "elixir"
    if low.startswith("proc "):
        return "nim"
    if "@import(\"std\")" in low or "@import('std')" in low:
        return "zig"
    if low.startswith("interface ") or low.startswith("type "):
        return "typescript"
    if low.startswith("using ") and not low.startswith("using system"):
        return "julia"
    if low.startswith("main =") or low.startswith("let "):
        return "haskell"
    if low.startswith("fn main"):
        return "rust"
    if low.startswith("console.") or low.startswith("function "):
        return "javascript"
    if low.startswith("//") and "console." in low:
        return "javascript"
    if low.startswith("echo ") or low.startswith("cd ") or low.startswith("ls "):
        return "bash"
    if low.startswith("import ") or low.startswith("from ") or low.startswith("def "):
        return "python"
    if re.match(r"print\s*\(", t):
        return "lua"
    if low.startswith("local "):
        return "lua"
    if re.match(r"print\s+['\"]", t) or low.startswith("use strict"):
        return "perl"
    if re.match(r"puts\s+['\"]", t):
        return "ruby"
    if low.startswith("cat(") or low.startswith("#"):
        return "r"
    if re.match(r"println\s+['\"]", t):
        return "groovy"
    if low.startswith("println("):
        return "julia"
    return "python"

def run_cmd(cmd, input_data=None, cwd=None):
    try:
        p = subprocess.run(cmd, input=input_data, text=True, cwd=cwd)
        return p.returncode
    except FileNotFoundError:
        eprint("Error: No such file or directory (os error 2)")
        return 1

def python_bin():
    return "/usr/bin/python3" if os.path.exists("/usr/bin/python3") else (shutil.which("python3") or "python3")

def bash_bin():
    return "/usr/bin/bash" if os.path.exists("/usr/bin/bash") else (shutil.which("bash") or "bash")

def perl_bin():
    return "/usr/bin/perl" if os.path.exists("/usr/bin/perl") else (shutil.which("perl") or "perl")

def run_python(mode, data):
    py = python_bin()
    if mode == "file":
        return run_cmd([py, data])
    if mode == "stdin":
        return run_cmd([py, "-"], input_data=data)
    return run_cmd([py, "-c", data])

def run_bash(mode, data):
    b = bash_bin()
    if mode == "file":
        return run_cmd([b, data])
    if mode == "stdin":
        return run_cmd([b], input_data=data)
    return run_cmd([b, "-c", data])

def run_perl(mode, data):
    p = perl_bin()
    if mode == "file":
        return run_cmd([p, data])
    if mode == "stdin":
        return run_cmd([p], input_data=data)
    return run_cmd([p, "-e", data])

def tempdir(prefix):
    return tempfile.mkdtemp(prefix=prefix, dir="/tmp")

def c_should_wrap(code):
    t = code.lstrip()
    if t.startswith("#include"):
        return False
    if re.search(r"\bmain\s*\(", code):
        return False
    return True

def write_file(path, text):
    with open(path, "w", encoding="utf-8") as f:
        f.write(text)

def copy_error(kind, src, dst, exc):
    eprint(f"Error: failed to copy {kind} source from {src} to {dst}")
    eprint()
    eprint("Caused by:")
    if isinstance(exc, OSError):
        msg = os.strerror(exc.errno) if exc.errno else str(exc)
        eprint(f"    {msg} (os error {exc.errno})")
    else:
        eprint(f"    {exc}")

def run_c(mode, data):
    gcc = shutil.which("gcc") or "gcc"
    d = tempdir("run-c")
    src = os.path.join(d, "main.c")
    exe = os.path.join(d, "main")
    try:
        if mode == "file":
            try:
                shutil.copyfile(data, src)
            except OSError as ex:
                copy_error("C", data, src, ex)
                return 1
        else:
            code = data or ""
            if c_should_wrap(code):
                code = "#include <stdio.h>\n#include <stdlib.h>\n\nint main(void) {\n" + "\n".join("    " + line if line else "" for line in code.splitlines()) + "\n    return 0;\n}\n"
            write_file(src, code)
        rc = run_cmd([gcc, src, "-o", exe])
        if rc != 0:
            return rc
        return run_cmd([exe])
    finally:
        shutil.rmtree(d, ignore_errors=True)

def run_cpp(mode, data):
    gpp = shutil.which("g++") or "g++"
    d = tempdir("run-cpp")
    src = os.path.join(d, "main.cpp")
    exe = os.path.join(d, "main")
    try:
        if mode == "file":
            try:
                shutil.copyfile(data, src)
            except OSError as ex:
                copy_error("C++", data, src, ex)
                return 1
        else:
            write_file(src, data or "")
        rc = run_cmd([gpp, src, "-o", exe])
        if rc != 0:
            return rc
        return run_cmd([exe])
    finally:
        shutil.rmtree(d, ignore_errors=True)

def go_bin():
    return shutil.which("go") or "/usr/local/go/bin/go"

def run_go(mode, data):
    go = go_bin()
    if mode == "file":
        path = data
        dirname = os.path.dirname(path)
        base = os.path.basename(path)
        if dirname == "":
            eprint(f"Error: failed to invoke {go} to run {path}")
            eprint()
            eprint("Caused by:")
            eprint("    No such file or directory (os error 2)")
            return 1
        cwd = dirname
        return run_cmd([go, "run", base], cwd=cwd)
    d = tempdir("run-go")
    src = os.path.join(d, "main.go")
    try:
        write_file(src, data or "")
        return run_cmd([go, "run", "main.go"], cwd=d)
    finally:
        shutil.rmtree(d, ignore_errors=True)

def rust_bin():
    return shutil.which("rustc") or "rustc"

def run_rust(mode, data):
    rustc = rust_bin()
    d = tempdir("run-rust")
    src = data if mode == "file" else os.path.join(d, "main.rs")
    exe = os.path.join(d, "main")
    try:
        if mode != "file":
            write_file(src, data or "")
        rc = run_cmd([rustc, "--crate-name", "run_snippet", src, "-o", exe])
        if rc != 0:
            return rc
        return run_cmd([exe])
    finally:
        shutil.rmtree(d, ignore_errors=True)

def run_javascript(mode, data):
    node = shutil.which("node")
    if not node:
        if mode == "stdin":
            eprint("Error: failed to start node for stdin execution")
            eprint()
            eprint("Caused by:")
            eprint("    No such file or directory (os error 2)")
        else:
            eprint("Error: No such file or directory (os error 2)")
        return 1
    if mode == "file":
        return run_cmd([node, data])
    if mode == "stdin":
        return run_cmd([node], input_data=data)
    return run_cmd([node, "-e", data])

def run_ruby(mode, data):
    ruby = shutil.which("ruby")
    if not ruby:
        if mode == "stdin":
            eprint("Error: failed to start ruby for stdin execution")
            eprint()
            eprint("Caused by:")
            eprint("    No such file or directory (os error 2)")
        else:
            eprint("Error: No such file or directory (os error 2)")
        return 1
    if mode == "file":
        return run_cmd([ruby, data])
    if mode == "stdin":
        return run_cmd([ruby], input_data=data)
    return run_cmd([ruby, "-e", data])

def run_typescript(mode, data):
    deno = shutil.which("deno")
    if not deno:
        if mode == "file":
            eprint("Error: failed to run Deno for file execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.")
        elif mode == "stdin":
            eprint("Error: failed to start Deno for stdin execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.")
        else:
            eprint("Error: failed to run Deno for inline execution because 'deno' was not found in PATH. Install Deno from https://deno.land/manual/getting_started/installation or ensure the binary is available on your PATH.")
        return 1
    if mode == "file":
        return run_cmd([deno, "run", data])
    if mode == "stdin":
        return run_cmd([deno, "run", "-"], input_data=data)
    return run_cmd([deno, "eval", data])

def run_lua(mode, data):
    lua = shutil.which("lua")
    if not lua:
        eprint(MISSING["lua"])
        return 1
    if mode == "file":
        return run_cmd([lua, data])
    if mode == "stdin":
        return run_cmd([lua], input_data=data)
    return run_cmd([lua, "-e", data])

def run_missing_or_simple(lang, mode, data):
    exe = REQUIRED_BIN.get(lang)
    if exe and not shutil.which(exe):
        eprint(MISSING[lang])
        return 1
    # Basic fallbacks for environments that happen to have these tools.
    if lang == "r":
        r = shutil.which("Rscript") or "Rscript"
        if mode == "file": return run_cmd([r, data])
        if mode == "stdin": return run_cmd([r, "-"], input_data=data)
        return run_cmd([r, "-e", data])
    if lang == "php":
        php = shutil.which("php") or "php"
        if mode == "file": return run_cmd([php, data])
        if mode == "stdin": return run_cmd([php], input_data=data)
        return run_cmd([php, "-r", data])
    if lang == "java":
        # Source-file mode if available; snippets are wrapped lightly.
        javac = shutil.which("javac") or "javac"
        java = shutil.which("java") or "java"
        d = tempdir("run-java")
        src = os.path.join(d, "Main.java")
        try:
            if mode == "file":
                try: shutil.copyfile(data, src)
                except OSError as ex:
                    copy_error("Java", data, src, ex); return 1
            else:
                code = data or ""
                if "class " in code:
                    write_file(src, code)
                else:
                    write_file(src, "public class Main { public static void main(String[] args) throws Exception {\n" + code + "\n}\n}\n")
            rc = run_cmd([javac, src], cwd=d)
            if rc != 0: return rc
            return run_cmd([java, "Main"], cwd=d)
        finally:
            shutil.rmtree(d, ignore_errors=True)
    # Interpreters/compilers not normally present in this benchmark.
    return 1

def run_language(lang, mode, data):
    if lang == "python": return run_python(mode, data)
    if lang == "bash": return run_bash(mode, data)
    if lang == "perl": return run_perl(mode, data)
    if lang == "c": return run_c(mode, data)
    if lang == "cpp": return run_cpp(mode, data)
    if lang == "go": return run_go(mode, data)
    if lang == "rust": return run_rust(mode, data)
    if lang == "javascript": return run_javascript(mode, data)
    if lang == "ruby": return run_ruby(mode, data)
    if lang == "typescript": return run_typescript(mode, data)
    if lang == "lua": return run_lua(mode, data)
    return run_missing_or_simple(lang, mode, data)

def validate_lang(s):
    lang = normalize_lang(s)
    if not lang:
        return None
    return lang

def lang_from_file(path, no_detect):
    if no_detect:
        return "python"
    return ext_language(path) or "python"

def app_error(msg):
    eprint("Error: " + msg)
    return 1

def resolve_and_run(state, args):
    explicit_lang_value = state["lang"]
    explicit_lang = None
    if explicit_lang_value is not None:
        explicit_lang = validate_lang(explicit_lang_value)
        if not explicit_lang:
            return unknown_language(explicit_lang_value)

    file_opt = state["file"]
    code_opt = state["code"]
    no_detect = state["no_detect"]

    if file_opt is not None and code_opt is not None:
        return app_error("--code/--inline cannot be combined with --file")

    if code_opt is not None:
        if code_opt.strip() == "":
            return app_error("Inline code provided via --code must not be empty")
        lang = explicit_lang
        if args:
            if explicit_lang is not None:
                return app_error("Unexpected positional arguments after specifying --code")
            if len(args) == 1 and is_lang(args[0]):
                lang = normalize_lang(args[0])
            else:
                return app_error("Unexpected positional arguments after specifying --code")
        if lang is None:
            lang = detect_language(code_opt, no_detect)
        return run_language(lang, "inline", code_opt)

    if file_opt is not None:
        lang = explicit_lang
        if args:
            if explicit_lang is not None:
                return app_error("Unexpected positional arguments when --file is present")
            if len(args) == 1 and is_lang(args[0]):
                lang = normalize_lang(args[0])
            else:
                return app_error("Unexpected positional arguments when --file is present")
        if lang is None:
            lang = lang_from_file(file_opt, no_detect)
        return run_language(lang, "file", file_opt)

    # No top-level --code/--file.
    if explicit_lang is not None:
        return resolve_with_language(explicit_lang, args, no_detect)

    if args and is_lang(args[0]):
        return resolve_with_language(normalize_lang(args[0]), args[1:], no_detect)

    if not args:
        if sys.stdin.isatty():
            return repl("python", no_detect)
        data = sys.stdin.read()
        if data == "":
            return 0
        lang = detect_language(data, no_detect)
        return run_language(lang, "stdin", data)

    if len(args) == 1 and looks_like_file(args[0]):
        path = args[0]
        lang = lang_from_file(path, no_detect)
        return run_language(lang, "file", path)

    code = " ".join(args)
    lang = detect_language(code, no_detect)
    return run_language(lang, "inline", code)

def resolve_with_language(lang, args, no_detect):
    if args:
        first = args[0]
        if first in ("--code", "-c"):
            if len(args) == 1:
                return app_error("--code/--inline requires a code argument")
            return run_language(lang, "inline", " ".join(args[1:]))
        if first in ("--file", "-f"):
            if len(args) == 1:
                return app_error("--file requires a path argument")
            if len(args) > 2:
                return app_error("Unexpected positional arguments after specifying --file")
            return run_language(lang, "file", args[1])
        if len(args) == 1 and looks_like_file(first):
            return run_language(lang, "file", first)
        return run_language(lang, "inline", " ".join(args))
    # Language selected but no code/file argument. Non-tty stdin is code, even when empty.
    if sys.stdin.isatty():
        return repl(lang, no_detect)
    data = sys.stdin.read()
    return run_language(lang, "stdin", data)

def repl(start_lang="python", no_detect=False):
    lang = start_lang
    auto = not no_detect
    print("run universal REPL. Type :help for commands.")
    while True:
        try:
            line = input(f"{lang}>>> ")
        except EOFError:
            return 0
        stripped = line.strip()
        if stripped in (":exit", ":quit"):
            print("bye")
            return 0
        if stripped == ":help":
            print("Commands:")
            print("  :help                 Show this help message")
            print("  :languages            List available languages")
            print("  :lang <id>            Switch to language <id>")
            print("  :detect on|off        Enable or disable auto language detection")
            print("  :reset                Reset the current language session")
            print("  :load <path>          Execute a file in the current language")
            print("  :exit, :quit          Leave the REPL")
            print("Any language id or alias works as a shortcut, e.g. :py, :cpp, :csharp, :php.")
            continue
        if stripped == ":languages":
            print(f"available languages: {AVAILABLE_STR}")
            continue
        if stripped.startswith(":detect "):
            val = stripped.split(None, 1)[1].strip().lower()
            if val == "on":
                auto = True; print("auto-detect enabled")
            elif val == "off":
                auto = False; print("auto-detect disabled")
            else:
                print("usage: :detect on|off")
            continue
        if stripped == ":reset":
            print(f"reset {lang}")
            continue
        if stripped.startswith(":lang "):
            val = stripped.split(None, 1)[1]
            nl = normalize_lang(val)
            if not nl:
                print(f"unknown language: {norm_key(val)}")
            elif nl == lang:
                print(f"already using {lang}")
            else:
                old = lang; lang = nl; print(f"switched {old} → {lang}")
            continue
        if stripped.startswith(":load "):
            path = stripped.split(None, 1)[1]
            rc = run_language(lang, "file", path)
            if rc != 0: return rc
            continue
        if stripped.startswith(":"):
            shortcut = normalize_lang(stripped[1:])
            if shortcut:
                if shortcut == lang:
                    print(f"already using {lang}")
                else:
                    old = lang; lang = shortcut; print(f"switched {old} → {lang}")
            else:
                print(f"unknown command: {stripped}. Type :help for help.")
            continue
        run_lang = lang
        if auto:
            det = detect_language(line, False)
            if det != lang:
                print(f"[auto-detect] switching {lang} → {det}")
                lang = det
                run_lang = det
        rc = run_language(run_lang, "inline", line)
        if rc != 0:
            return rc

def main():
    try:
        state, args = parse_argv(sys.argv[1:])
        rc = resolve_and_run(state, args)
        raise SystemExit(rc)
    except BrokenPipeError:
        raise SystemExit(1)

if __name__ == "__main__":
    main()
